# whisper_from_sssDeMoNsss -- Full Installer (PowerShell)
# Run as Administrator:
#   powershell -ExecutionPolicy Bypass -File "C:\whisper-ptt\install-whisper-ptt.ps1"
#
# Place in same folder:
#   install-whisper-ptt.ps1  <- this file
#   whisper-ptt.py           <- your custom file
#   config.toml              <- your custom file
#
# Optional: specify WhisperServer port (default 9000):
#   powershell -ExecutionPolicy Bypass -File "...\install-whisper-ptt.ps1" -ServerPort 9001

# -- Port parameter -- port of WhisperServer to write into config.toml ----------
param(
    [int]$ServerPort    = 9000,
    [int]$GpuIndex      = -99,   # -99 = не передан → интерактивный опрос
    [string]$GpuDevice  = "",    # "cuda" или "cpu"
    [string]$GpuModel   = "",    # модель для PTT fallback
    [string]$GpuCompute = ""     # "float16" или "int8"
)

# -- DO NOT use Stop -- lets us handle errors gracefully ------------------------
$ErrorActionPreference = "Continue"

# -- Version selection --------------------------------------------------------
Write-Host ""
Write-Host "  Which version do you want to install? (Kakuyu versiyu vyibrat dlya ustanovki?)" -ForegroundColor White
Write-Host ""
Write-Host "  [1]  whisper_from_sssDeMoNsss_RU-ENG" -ForegroundColor Green
Write-Host "       Speak RUSSIAN  -> Right Ctrl = Russian text  (Govori po-RUSSKI -> Praviy Ctrl = russkiy tekst)" -ForegroundColor Gray
Write-Host "       Speak RUSSIAN  -> Right Alt  = English text (translate)  (Praviy Alt = angliyskiy tekst, perevod)" -ForegroundColor Gray
Write-Host ""
Write-Host "  [2]  whisper_from_sssDeMoNsss_ENG-RU" -ForegroundColor Cyan
Write-Host "       Speak ENGLISH  -> Right Ctrl = English text  (Govori po-ANGLIYSKI -> Praviy Ctrl = angliyskiy tekst)" -ForegroundColor Gray
Write-Host "       Speak ENGLISH  -> Right Alt  = Russian text (translate)  (Praviy Alt = russkiy tekst, perevod)" -ForegroundColor Gray
Write-Host ""
$versionChoice = Read-Host "  Enter 1 or 2 (Vvedite 1 ili 2)"
$versionChoice = $versionChoice.Trim()

if ($versionChoice -eq "2") {
    $VERSION_NAME  = "whisper_from_sssDeMoNsss_ENG-RU"
    $INSTALL_DIR   = "C:\whisper-ptt-eng"
    $SHORTCUT_NAME = "Whisper PTT ENG-RU"
    $TASK_NAME     = "Whisper PTT ENG-RU Autostart"
    $USE_ENG_MODE  = $true
    Write-Host ""
    Write-Host "  Installing: $VERSION_NAME  (Ustanovka: $VERSION_NAME)" -ForegroundColor Cyan
    Write-Host "  Directory : $INSTALL_DIR  (Papka ustanovki: $INSTALL_DIR)" -ForegroundColor Cyan
} else {
    $VERSION_NAME  = "whisper_from_sssDeMoNsss_RU-ENG"
    $INSTALL_DIR   = "C:\whisper-ptt"
    $SHORTCUT_NAME = "Whisper PTT RU-ENG"
    $TASK_NAME     = "Whisper PTT Autostart"
    $USE_ENG_MODE  = $false
    Write-Host ""
    Write-Host "  Installing: $VERSION_NAME  (Ustanovka: $VERSION_NAME)" -ForegroundColor Green
    Write-Host "  Directory : $INSTALL_DIR  (Papka ustanovki: $INSTALL_DIR)" -ForegroundColor Green
}
Write-Host ""
# -----------------------------------------------------------------------------

$FFMPEG_DIR  = "C:\ffmpeg"

# -- Helper functions ----------------------------------------------------------
function Write-Step($n, $text) {
    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host "  STEP ${n}: $text" -ForegroundColor Cyan
    Write-Host "============================================================" -ForegroundColor Cyan
    Write-Host ""
}
function Write-OK($text)   { Write-Host "[OK]    $text" -ForegroundColor Green   }
function Write-Warn($text) { Write-Host "[!]     $text" -ForegroundColor Yellow  }
function Write-Err($text)  { Write-Host "[ERROR] $text" -ForegroundColor Red     }
function Write-Fix($text)  { Write-Host "[FIX]   $text" -ForegroundColor Magenta }

