# -- Find ffmpeg.exe in WinGet packages (versioned path) ----------------------
function Find-FfmpegInWinGet {
    $wingetBase = "$env:LOCALAPPDATA\Microsoft\WinGet\Packages"
    if (-not (Test-Path $wingetBase)) { return $null }
    $dirs = Get-ChildItem $wingetBase -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -like "Gyan.FFmpeg*" }
    foreach ($d in $dirs) {
        $ff = Get-ChildItem $d.FullName -Recurse -Filter "ffmpeg.exe" -ErrorAction SilentlyContinue |
              Select-Object -First 1
        if ($ff) { return $ff.DirectoryName }
    }
    return $null
}

# -- Banner --------------------------------------------------------------------
Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "                                                            " -ForegroundColor Cyan
Write-Host "   whisper_from_sssDeMoNsss                                " -ForegroundColor White
Write-Host "   govori, ne pechatat.                                    " -ForegroundColor White
Write-Host "                                                            " -ForegroundColor Cyan
Write-Host "   Avtor   : sssDeMoNsss                                   " -ForegroundColor Gray
Write-Host "   Ustanovka v: $INSTALL_DIR                               " -ForegroundColor Gray
Write-Host "                                                            " -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host ""

# -- Admin check ---------------------------------------------------------------
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
           [Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Err "Run as Administrator! Right-click -> Run as administrator (Zapustite kak Administrator! Pravaya knopka myshi -> Zapusk ot imeni administratora)"
    Read-Host "Press Enter to exit (Nazhmite Enter dlya vyhoda)"; exit 1
}
Write-OK "Administrator rights confirmed (Prava administratora podtverzhdeny)"

# =============================================================================
Write-Step 1 "Find Python (Shag 1: Naiti Python)"
# =============================================================================

$PYTHON_EXE = $null

# 1. Known install locations (user and system)
$candidates = @(
    "$env:LOCALAPPDATA\Programs\Python\Python313\python.exe",
    "$env:LOCALAPPDATA\Programs\Python\Python312\python.exe",
    "$env:LOCALAPPDATA\Programs\Python\Python311\python.exe",
    "$env:LOCALAPPDATA\Programs\Python\Python310\python.exe",
    "C:\Python313\python.exe",
    "C:\Python312\python.exe",
    "C:\Python311\python.exe",
    "C:\Python310\python.exe",
    "C:\Program Files\Python313\python.exe",
    "C:\Program Files\Python312\python.exe",
    "C:\Program Files\Python311\python.exe"
)
foreach ($c in $candidates) {
    if (Test-Path $c) { $PYTHON_EXE = $c; break }
}

# 2. Fallback: where.exe -- skip WindowsApps stub
if (-not $PYTHON_EXE) {
    $whereOut = & where.exe python 2>&1
    if ($LASTEXITCODE -eq 0) {
        foreach ($p in $whereOut) {
            $p = $p.Trim()
            if ($p -and ($p -notlike "*WindowsApps*") -and (Test-Path $p)) {
                $PYTHON_EXE = $p; break
            }
        }
    }
}

if (-not $PYTHON_EXE) {
    Write-Err "Python not found! (Python ne nayden!)"
    Write-Host ""
    Write-Host "  Install Python 3.12: https://www.python.org/downloads/ (Ustanovite Python 3.12)" -ForegroundColor Yellow
    Write-Host "  During install check box: Add Python to PATH (Pri ustanovke otmetit: Add Python to PATH)"           -ForegroundColor Yellow
    Write-Host ""
    Write-Host "  Then add to system PATH (PowerShell Admin): (Zatem dobavit v sistemniy PATH, PowerShell Admin):" -ForegroundColor Gray
    Write-Host '  $p=[System.Environment]::GetEnvironmentVariable("Path","Machine")' -ForegroundColor Gray
    Write-Host '  [System.Environment]::SetEnvironmentVariable("Path","$p;$env:LOCALAPPDATA\Programs\Python\Python312;$env:LOCALAPPDATA\Programs\Python\Python312\Scripts","Machine")' -ForegroundColor Gray
    Read-Host "Press Enter to exit (Nazhmite Enter dlya vyhoda)"; exit 1
}

Write-Fix "Using Python: $PYTHON_EXE (Ispolzuyem Python: $PYTHON_EXE)"
$pyver = & $PYTHON_EXE --version 2>&1
Write-OK "$pyver"

# Version check >= 3.10
$pyVerStr = & $PYTHON_EXE -c "import sys; print(f'{sys.version_info.major}.{sys.version_info.minor}')" 2>&1
try {
    if ([version]$pyVerStr -lt [version]"3.10") {
        Write-Err "Python 3.10+ required. Found: $pyver (Trebuetsya Python 3.10+. Nayden: $pyver)"
        Read-Host "Press Enter to exit (Nazhmite Enter dlya vyhoda)"; exit 1
    }
} catch {
    Write-Warn "Could not parse Python version, continuing anyway... (Versiya Python ne opredelen, prodolzhaem)"
}

# =============================================================================
Write-Step 2 "Check / Install FFmpeg (Shag 2: Proverit / Ustanovit FFmpeg)"
# =============================================================================

function Test-Ffmpeg {
    # Use Get-Command to silently check existence -- avoids visible CommandNotFoundException
    $cmd = Get-Command ffmpeg -ErrorAction SilentlyContinue
    if (-not $cmd) { return $false }
    return $true
}

function Add-FfmpegPath($dir) {
    if ($dir -and (Test-Path "$dir\ffmpeg.exe")) {
        $env:PATH = $dir + ";" + $env:PATH
        Write-Fix "FFmpeg added to PATH: $dir (FFmpeg dobavlen v PATH: $dir)"
        return $true
    }
    return $false
}

$ffmpegReady = $false

# 1. Already in PATH?
if (Test-Ffmpeg) {
    Write-OK "FFmpeg already in PATH (FFmpeg uzhe est v PATH)"
    $ffmpegReady = $true
}

# 2. Check known static locations
if (-not $ffmpegReady) {
    $staticLocations = @(
        "C:\ffmpeg\bin",
        "C:\ProgramData\chocolatey\bin",
        "$env:ProgramFiles\ffmpeg\bin",
        "$env:ProgramFiles\ffmpeg"
    )
    foreach ($loc in $staticLocations) {
        if (Add-FfmpegPath $loc) { $ffmpegReady = $true; break }
    }
}

# 3. Check WinGet packages (Gyan.FFmpeg installed via winget)
if (-not $ffmpegReady) {
    $wgDir = Find-FfmpegInWinGet
    if ($wgDir) {
        if (Add-FfmpegPath $wgDir) { $ffmpegReady = $true }
    }
}

# 4. Install via winget
if (-not $ffmpegReady) {
    Write-Warn "FFmpeg not found. Trying winget... (FFmpeg ne nayden. Probuyem winget...)"
    & winget install Gyan.FFmpeg --silent --accept-package-agreements --accept-source-agreements 2>&1 | Out-Null

    # Reload system PATH from registry
    $sysPath = [System.Environment]::GetEnvironmentVariable("Path", "Machine")
    $env:PATH = $sysPath + ";" + $env:PATH

    # Search WinGet packages (winget installs to versioned directory)
    $wgDir = Find-FfmpegInWinGet
    if ($wgDir -and (Add-FfmpegPath $wgDir)) {
        Write-OK "FFmpeg found via winget at: $wgDir (FFmpeg nayden cherez winget: $wgDir)"
        $ffmpegReady = $true
    } elseif (Test-Ffmpeg) {
        Write-OK "FFmpeg installed via winget (FFmpeg ustanovlen cherez winget)"
        $ffmpegReady = $true
    }
}

# 5. Install via Chocolatey
if (-not $ffmpegReady) {
    Write-Warn "winget ne srabotan. Probuyem Chocolatey... (winget ne srabotan. Trying Chocolatey...)"
    $chocoExe = "C:\ProgramData\chocolatey\bin\choco.exe"
    if (Test-Path $chocoExe) {
        & $chocoExe install ffmpeg -y 2>&1 | Out-Null
        if (Add-FfmpegPath "C:\ProgramData\chocolatey\bin") {
            Write-OK "FFmpeg installed via Chocolatey (FFmpeg ustanovlen cherez Chocolatey)"
            $ffmpegReady = $true
        }
    } else {
        Write-Warn "Chocolatey not found. (Chocolatey ne nayden.)"
    }
}

# 6. Manual download (~130 MB)
if (-not $ffmpegReady) {
    Write-Warn "Downloading FFmpeg manually (~130 MB)... (Skachivayem FFmpeg vruchnuyu, ~130 MB...)"
    try {
        $ffUrl = "https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-win64-gpl.zip"
        $ffZip = "$env:TEMP\ffmpeg.zip"
        $ffTmp = "$env:TEMP\ffmpeg_extract"
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        (New-Object Net.WebClient).DownloadFile($ffUrl, $ffZip)
        if (Test-Path $ffTmp) { Remove-Item $ffTmp -Recurse -Force }
        Expand-Archive -Path $ffZip -DestinationPath $ffTmp -Force
        $inner = Get-ChildItem $ffTmp -Directory | Select-Object -First 1
        if (-not (Test-Path "$FFMPEG_DIR\bin")) { New-Item "$FFMPEG_DIR\bin" -ItemType Directory -Force | Out-Null }
        Copy-Item "$($inner.FullName)\bin\*" "$FFMPEG_DIR\bin\" -Force -ErrorAction SilentlyContinue
        Remove-Item $ffZip -Force -ErrorAction SilentlyContinue
        Remove-Item $ffTmp -Recurse -Force -ErrorAction SilentlyContinue
        # Add to current PATH
        $env:PATH = "$FFMPEG_DIR\bin;" + $env:PATH
        # Save to system PATH permanently
        $sysPath = [System.Environment]::GetEnvironmentVariable("Path", "Machine")
        if ($sysPath -notlike "*$FFMPEG_DIR\bin*") {
            [System.Environment]::SetEnvironmentVariable("Path", "$sysPath;$FFMPEG_DIR\bin", "Machine")
            Write-Fix "FFmpeg added to system PATH permanently (FFmpeg dobavlen v sistemniy PATH navsegda)"
        }
        Write-OK "FFmpeg installed to $FFMPEG_DIR (FFmpeg ustanovlen v $FFMPEG_DIR)"
        $ffmpegReady = $true
    } catch {
        Write-Err "Failed to download FFmpeg: $_ (Oshibka zagruzki FFmpeg: $_)"
        Write-Host "  Install manually: https://github.com/BtbN/FFmpeg-Builds/releases (Ustanovite vruchnuyu)" -ForegroundColor Yellow
        Write-Host "  whisper-ptt.py will also auto-search for FFmpeg on startup. (whisper-ptt.py sam naydet FFmpeg pri zapuske)" -ForegroundColor Yellow
    }
}

# Final FFmpeg status
if (Test-Ffmpeg) {
    Write-OK "FFmpeg working in current session (FFmpeg rabotaet v tekushchey sessii)"
} else {
    Write-Warn "FFmpeg not in current session PATH -- whisper-ptt.py will find it automatically on startup (whisper-ptt.py naydet FFmpeg avtomaticheski pri zapuske)"
}

# =============================================================================
Write-Step 3 "Install whisper_platform module (Shag 3: Ustanovit modul whisper_platform)"
# =============================================================================
# whisper_platform is embedded directly in this installer -- no GitHub needed.
