if (-not (Test-Path $INSTALL_DIR)) {
    New-Item $INSTALL_DIR -ItemType Directory -Force | Out-Null
}

Install-WhisperPlatform $INSTALL_DIR
Install-OptionalScripts $INSTALL_DIR

