Write-Step 4 "Apply main script (Shag 4: Primenit glavniy skript)"
# =============================================================================
# ENG-RU: embed whisper-ptt-eng.py  |  RU-ENG: copy whisper-ptt.py from installer dir

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path

if ($USE_ENG_MODE) {
    $b64EngPy = ""
    [System.IO.File]::WriteAllBytes("$INSTALL_DIR\whisper-ptt-eng.py", [System.Convert]::FromBase64String($b64EngPy))
    Write-OK "whisper-ptt-eng.py applied (EN language + EN->RU translation) (whisper-ptt-eng.py primenen, yazyk EN + perevod EN->RU)"
} else {
    $srcPy = Join-Path $scriptDir "whisper-ptt.py"
    $dstPy = "$INSTALL_DIR\whisper-ptt.py"
    if (Test-Path $srcPy) {
        $srcAbs = (Resolve-Path $srcPy).Path
        $dstAbs = if (Test-Path $dstPy) { (Resolve-Path $dstPy).Path } else { "" }
        if ($srcAbs -ne $dstAbs) {
            Copy-Item $srcPy $dstPy -Force
            Write-OK "whisper-ptt.py applied (RU language + ffmpeg auto-fix) (whisper-ptt.py primenen, yazyk RU + avto-fix ffmpeg)"
        } else {
            Write-OK "whisper-ptt.py already in place (running from install dir) (whisper-ptt.py uzhe na meste, zapusk iz papki ustanovki)"
        }
    } else {
        Write-Warn "whisper-ptt.py NOT FOUND next to installer! (whisper-ptt.py NE NAYDEN ryadom s ustanovshchikom!)"
        Write-Warn "Place whisper-ptt.py in the same folder as install-whisper-ptt.ps1 (Polozhite whisper-ptt.py v tu zhe papku chto i ustanovshchik)"
    }
}

Write-Step 5 "Apply config.toml (Shag 5: Primenit nastroyki config.toml)"
# =============================================================================

if ($USE_ENG_MODE) {
    $b64EngCfg = ""
    [System.IO.File]::WriteAllBytes("$INSTALL_DIR\config.toml", [System.Convert]::FromBase64String($b64EngCfg))
    Write-OK "config.toml applied (language=en, model=small, EN->RU mode) (config.toml primenen, yazyk=en, model=small, rezhim EN->RU)"
} else {
    $srcCfg = Join-Path $scriptDir "config.toml"
    $dstCfg = "$INSTALL_DIR\config.toml"
    if (Test-Path $srcCfg) {
        $srcCfgAbs = (Resolve-Path $srcCfg).Path
        $dstCfgAbs = if (Test-Path $dstCfg) { (Resolve-Path $dstCfg).Path } else { "" }
        if ($srcCfgAbs -ne $dstCfgAbs) {
            Copy-Item $srcCfg $dstCfg -Force
            Write-OK "config.toml applied (model=medium, language=ru, RTX 3070 Ti) (config.toml primenen, model=medium, yazyk=ru)"
        } else {
            Write-OK "config.toml already in place (running from install dir) (config.toml uzhe na meste, zapusk iz papki ustanovki)"
        }
    } else {
        Write-Warn "config.toml NOT FOUND next to installer -- creating default... (config.toml NE NAYDEN ryadom s ustanovshchikom -- sozdayem po umolchaniyu...)"
        # Use double-quoted here-string so $ServerPort gets expanded
        $defaultCfg = @"
# Whisper Push-to-Talk Konfiguratsiya dlya RTX 3070 Ti
# ==============================================================
# REMOTE TRANSCRIPTION SERVER (localnyy server transkriptsii)
# ==============================================================
# WhisperServer runs locally on port $ServerPort
# (Port configured during installation -- change here if moved)
[remote]
enabled = false
url = "http://localhost:$ServerPort"
timeout = 30

[hotkey]
# VNIMANIE: Win+H konfliktuet s golosovym vvodom Windows
# Rekomenduetsya ispol'zovat' druguyu kombinatsiyu
# Varianty: ctrl_r, alt_r, shift_r, f13-f24, ili kombinatsii
key = "ctrl_r"

# Klavisha dlya rezhima PEREVODA (RU -> EN)
# Zazhat' -> speakt' po-russki -> otpustit' -> tekst vstavitsya na ANGLIYSKOM
# Po umolchaniyu: Pravyy Alt
translate_key = "alt_r"

[whisper]
# Model' dlya russkogo yazyka
# Dlya GPU mozhno ispol'zovat' bolee tochnye modeli:
# base = bystro, khorosho (1 sek na RTX 3070 Ti)
# small = tochnee, vsyo eshchyo bystro (1-2 sek na RTX 3070 Ti)
# medium = ochen' tochno (2-3 sek na RTX 3070 Ti) i ochen' kachestvennyy golosovoy vvod.
# large-v2 = maksimal'no tochno (8-12 sek). Trebuetsya 5090 ti dlya bystroy raboty etoy modeli.
model = "medium"

# Yazyk
language = "ru"

# USTROYSTVO DLYa VYChISLENIY
# auto   = opredelyaetsya avtomaticheski (rekomenduetsya)
# cuda   = NVIDIA GPU (Windows / Linux)
# mps    = Apple Silicon GPU (macOS M1/M2/M3/M4)
# cpu    = protsessor (lyubaya platforma, medlennee)
device = "auto"
compute_type = "float16"

# Fil'tr golosovoy aktivnosti
vad_filter = true
vad_min_silence_duration_ms = 800

[audio]
sample_rate = 16000
channels = 1

[paste]
method = "both"
add_trailing_space = true
auto_capitalize = true

[notifications]
enabled = true
show_recording = false
show_transcribing = true
show_result = true

[tray]
enabled = true

[logging]
verbose = false
show_audio_diagnostics = false
show_transcription_diagnostics = false
"@
        $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
        [System.IO.File]::WriteAllText($dstCfg, $defaultCfg, $utf8NoBom)
        Write-OK "Default config.toml created (Russian defaults) (Standartnyy config.toml sozdan, nastroyki dlya russkogo yazyka)"
    }
}

# -- Patch remote URL in config.toml with correct port -------------------------
# Runs regardless of which branch above wrote the config.toml.
# Ensures url = "http://localhost:<ServerPort>" is correct.
if (Test-Path "$INSTALL_DIR\config.toml") {
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    $cfgRaw = Get-Content "$INSTALL_DIR\config.toml" -Raw -Encoding UTF8

    if ($cfgRaw -match '\[remote\]') {
        # Update existing [remote] url line
        $cfgRaw = $cfgRaw -replace 'url\s*=\s*"http://[^"]*"', "url = `"http://localhost:$ServerPort`""
    } else {
        # Prepend [remote] section if missing (e.g. copied from old config.toml)
        $remoteBlock = @"
# ==============================================================
# REMOTE TRANSCRIPTION SERVER -- port configured at install time
# ==============================================================
[remote]
enabled = false
url = "http://localhost:$ServerPort"
timeout = 30

"@
        $cfgRaw = $remoteBlock + $cfgRaw
    }
    [System.IO.File]::WriteAllText("$INSTALL_DIR\config.toml", $cfgRaw, $utf8NoBom)
    Write-OK "config.toml: remote.url set to http://localhost:$ServerPort"
}

Write-Step 6 "Install Python dependencies (Shag 6: Ustanovit zavisimosti Python)"
# =============================================================================

Set-Location $INSTALL_DIR

Write-Host "  Upgrading pip... (Obnovleniye pip...)"
& $PYTHON_EXE -m pip install --upgrade pip --quiet
Write-OK "pip upgraded (pip obnovlen)"

Write-Host "  Installing packages... (Ustanovka paketov...)"
& $PYTHON_EXE -m pip install openai-whisper sounddevice numpy pynput pystray pillow tomli pywin32 colorama
if ($LASTEXITCODE -ne 0) {
    Write-Err "Failed to install packages. Check internet connection. (Oshibka ustanovki paketov. Proverte podklyucheniye k internetu.)"
    Read-Host "Press Enter to exit (Nazhmite Enter dlya vyhoda)"; exit 1
}
if ($USE_ENG_MODE) {
    Write-Host "  Installing deep-translator (EN->RU translation)... (Ustanovka deep-translator dlya perevoda EN->RU...)"
    & $PYTHON_EXE -m pip install deep-translator
    if ($LASTEXITCODE -ne 0) {
        Write-Warn "deep-translator failed to install. EN->RU translation (Right Alt) requires internet + deep-translator. (Oshibka ustanovki deep-translator. Perevod EN->RU trebuyet internet + deep-translator.)"
        Write-Warn "Install manually: pip install deep-translator (Ustanovite vruchnuyu: pip install deep-translator)"
    } else {
        Write-OK "deep-translator installed (deep-translator ustanovlen)"
    }
}
Write-OK "All packages installed (Vse pakety ustanovleny)"

# =============================================================================
Write-Step 7 "Install PyTorch with CUDA + verify (Shag 7: Ustanovka PyTorch i proverka)"
# =============================================================================

# -- Choose correct PyTorch CUDA index based on Python version ----------------
# cu121 index has NO wheels for Python 3.13+ (torchaudio missing entirely).
# Python 3.13+ requires cu124 or newer.  cu124 ships CUDA 12.x DLLs that
# faster-whisper needs (cublas64_12.dll, cudnn_ops_infer64_8.dll) — same as cu121.
# Python <=3.12: cu121 still works fine, keep it for backward compat.
$pyMinorStr = (& $PYTHON_EXE -c "import sys; print(sys.version_info.minor)" 2>&1).Trim()
$pyMinor = if ($pyMinorStr -match "^\d+$") { [int]$pyMinorStr } else { 12 }
$pyMajorStr = (& $PYTHON_EXE -c "import sys; print(sys.version_info.major)" 2>&1).Trim()
$pyMajor = if ($pyMajorStr -match "^\d+$") { [int]$pyMajorStr } else { 3 }

# Python 3.13+ → cu124 (first index with full Python 3.13 wheels)
# Python 3.10–3.12 → cu121 (proven stable for faster-whisper)
if ($pyMajor -gt 3 -or ($pyMajor -eq 3 -and $pyMinor -ge 13)) {
    $TORCH_INDEX     = "https://download.pytorch.org/whl/cu124"
    $TORCH_INDEX_FB  = "https://download.pytorch.org/whl/cu126"  # fallback
    $CUDA_INDEX_NAME = "cu124"
} else {
    $TORCH_INDEX     = "https://download.pytorch.org/whl/cu121"
    $TORCH_INDEX_FB  = "https://download.pytorch.org/whl/cu124"  # fallback if cu121 fails
    $CUDA_INDEX_NAME = "cu121"
}
Write-Host "  Python $pyMajor.$pyMinor detected -> using PyTorch index: $CUDA_INDEX_NAME" -ForegroundColor Cyan

# -- Detect current PyTorch state ---------------------------------------------
$existingCuda = ""
$torchImportOk = $false
& $PYTHON_EXE -c "import torch" 2>&1 | Out-Null
if ($LASTEXITCODE -eq 0) {
    $torchImportOk = $true
    $existingCuda = (& $PYTHON_EXE -c "import torch; print(torch.version.cuda or '')" 2>&1).Trim()
}

# Helper: reinstall PyTorch using the version-appropriate index
function Install-PyTorch($indexUrl, $indexName) {
    Write-Host "  Installing PyTorch $indexName (~2-3 GB, may take 5-10 min)..." -ForegroundColor Yellow
    & $PYTHON_EXE -m pip install torch torchvision torchaudio --index-url $indexUrl
    return $LASTEXITCODE -eq 0
}

if ($existingCuda -like "11.*") {
    # CUDA 11 → must upgrade: faster-whisper needs cublas64_12.dll (CUDA 12 only)
    Write-Host ""
    Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkYellow
    Write-Host "  UPGRADING PyTorch: cu118 -> $CUDA_INDEX_NAME" -ForegroundColor Yellow
    Write-Host "  faster-whisper requires CUDA 12 (cublas64_12.dll)." -ForegroundColor Yellow
    Write-Host "  (faster-whisper trebuyet CUDA 12 -- obnovlyayem PyTorch)" -ForegroundColor DarkYellow
    Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkYellow
    Write-Host ""
    & $PYTHON_EXE -m pip uninstall torch torchvision torchaudio -y 2>&1 | Out-Null
    if (-not (Install-PyTorch $TORCH_INDEX $CUDA_INDEX_NAME)) {
        Write-Warn "$CUDA_INDEX_NAME failed -- trying fallback $TORCH_INDEX_FB..."
        Install-PyTorch $TORCH_INDEX_FB "cu124/cu126 fallback" | Out-Null
    }
    $existingCuda = (& $PYTHON_EXE -c "import torch; print(torch.version.cuda or 'n/a')" 2>&1).Trim()
    Write-OK "PyTorch upgraded. CUDA version now: $existingCuda"

} elseif (-not $torchImportOk -or $existingCuda -eq "") {
    # PyTorch not found at all — fresh install
    Write-Host "  PyTorch not found -- installing $CUDA_INDEX_NAME..." -ForegroundColor Yellow
    if (-not (Install-PyTorch $TORCH_INDEX $CUDA_INDEX_NAME)) {
        Write-Warn "$CUDA_INDEX_NAME failed -- trying fallback $TORCH_INDEX_FB..."
        if (-not (Install-PyTorch $TORCH_INDEX_FB "cu124/cu126 fallback")) {
            Write-Warn "All CUDA indexes failed -- installing CPU-only as last resort..."
            & $PYTHON_EXE -m pip install torch torchvision torchaudio --index-url https://download.pytorch.org/whl/cpu
        }
    }

} elseif ($existingCuda -like "12.*") {
    # CUDA 12.x already installed — check if it came from the wrong index
    # (e.g. torch 2.10.0+cpu from PyPI, or wrong cu121 on Python 3.13)
    $torchTag = (& $PYTHON_EXE -c "import torch; print(torch.__version__)" 2>&1).Trim()
    $needsReinstall = $false

    # Detect CPU-only build mistakenly installed (tag ends with +cpu)
    if ($torchTag -like "*+cpu*") {
        Write-Warn "Detected CPU-only torch ($torchTag) -- reinstalling with CUDA $CUDA_INDEX_NAME..."
        $needsReinstall = $true
    }
    # On Python 3.13+: cu121 index cannot provide torchaudio, so force switch to cu124
    elseif ($pyMajor -eq 3 -and $pyMinor -ge 13 -and $CUDA_INDEX_NAME -eq "cu124") {
        # Check if torchaudio is actually installed correctly
        & $PYTHON_EXE -c "import torchaudio" 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) {
            Write-Warn "torchaudio missing on Python 3.13 (cu121 has no py3.13 wheels) -- reinstalling with cu124..."
            $needsReinstall = $true
        }
    }

    if ($needsReinstall) {
        & $PYTHON_EXE -m pip uninstall torch torchvision torchaudio -y 2>&1 | Out-Null
        if (-not (Install-PyTorch $TORCH_INDEX $CUDA_INDEX_NAME)) {
            Write-Warn "Reinstall failed -- trying fallback..."
            Install-PyTorch $TORCH_INDEX_FB "cu124/cu126 fallback" | Out-Null
        }
        $existingCuda = (& $PYTHON_EXE -c "import torch; print(torch.version.cuda or 'n/a')" 2>&1).Trim()
        Write-OK "PyTorch reinstalled. CUDA: $existingCuda"
    } else {
        Write-OK "PyTorch CUDA $existingCuda already installed -- no upgrade needed."
    }

} else {
    Write-OK "PyTorch CUDA $existingCuda already installed -- no upgrade needed."
}

# -- GPU/model config for PTT client ------------------------------------------
# Когда мастер передал GPU-данные — используем их напрямую, не переспрашиваем.
# Когда запуск standalone — определяем GPU сами.

$cfgPath = "$INSTALL_DIR\config.toml"

if ($GpuIndex -ne -99 -and $GpuDevice -ne "" -and $GpuModel -ne "" -and $GpuCompute -ne "") {
    # ── Данные пришли из мастера — просто применяем ──────────────────────────
    $deviceString = if ($GpuIndex -le 0) { "cuda" } else { "cuda:$GpuIndex" }
    if ($GpuDevice -eq "cpu") { $deviceString = "cpu" }

    $chosenModel  = $GpuModel
    $computeType  = $GpuCompute

    Write-OK "GPU config received from master installer:"
    Write-Host "    GPU index    : $GpuIndex" -ForegroundColor Cyan
    Write-Host "    device       : $deviceString" -ForegroundColor Cyan
    Write-Host "    model        : $chosenModel" -ForegroundColor Cyan
    Write-Host "    compute_type : $computeType" -ForegroundColor Cyan

    if (Test-Path $cfgPath) {
        $cfgContent = Get-Content $cfgPath -Raw
        $cfgContent = $cfgContent -replace 'model\s*=\s*"[^"]+"',        "model = `"$chosenModel`""
        $cfgContent = $cfgContent -replace 'device\s*=\s*"[^"]+"',       "device = `"$deviceString`""
        $cfgContent = $cfgContent -replace 'compute_type\s*=\s*"[^"]+"', "compute_type = `"$computeType`""
        $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
        [System.IO.File]::WriteAllText($cfgPath, $cfgContent, $utf8NoBom)
        Write-OK "config.toml updated: model=$chosenModel  device=$deviceString  compute_type=$computeType"
    }

} else {
    # ── Standalone запуск — полный интерактивный GPU-анализ ──────────────────

    function Get-OptimalModel($vramMB, $isEng) {
        $vram = [int]$vramMB
        if ($isEng) {
            if     ($vram -ge 6000)  { return "medium" }
            elseif ($vram -ge 3000)  { return "small" }
            elseif ($vram -ge 1500)  { return "base" }
            else                     { return "tiny" }
        } else {
            if     ($vram -ge 6000)  { return "large-v2" }
            elseif ($vram -ge 3000)  { return "medium" }
            elseif ($vram -ge 1300)  { return "small" }
            else                     { return "base" }
        }
    }
    function Get-VramReq($model) {
        switch ($model) {
            "tiny"     { return 500 }
            "base"     { return 700 }
            "small"    { return 1300 }
            "medium"   { return 3000 }
            "large-v2" { return 5500 }
            default    { return 99999 }
        }
    }
    function Get-QualityLabel($model) {
        switch ($model) {
            "large-v2" { return "MAXIMUM quality  -- best for Russian" }
            "medium"   { return "HIGH quality     -- excellent for everyday use" }
            "small"    { return "GREAT quality    -- fast and accurate" }
            "base"     { return "GOOD quality     -- fast, lower accuracy" }
            "tiny"     { return "BASIC quality    -- fastest, lowest accuracy" }
            default    { return "unknown" }
        }
    }

    & $PYTHON_EXE -c "import torch; exit(0 if torch.cuda.is_available() else 1)" 2>&1 | Out-Null
    if ($LASTEXITCODE -eq 0) {

        $gpuCount = [int](& $PYTHON_EXE -c "import torch; print(torch.cuda.device_count())" 2>&1).Trim()
        $cudaVer  = (& $PYTHON_EXE -c "import torch; print(torch.version.cuda)" 2>&1).Trim()
        Write-OK "PyTorch + CUDA $cudaVer installed."
        Write-Host ""
        Write-Host "  GPU Analysis -- $gpuCount GPU(s) detected:" -ForegroundColor Cyan

        $gpuInfos = @()
        for ($i = 0; $i -lt $gpuCount; $i++) {
            $name   = (& $PYTHON_EXE -c "import torch; print(torch.cuda.get_device_name($i))" 2>&1).Trim()
            $vram   = (& $PYTHON_EXE -c "import torch; print(torch.cuda.get_device_properties($i).total_memory // 1024 // 1024)" 2>&1).Trim()
            $vramGB = [math]::Round([int]$vram / 1024, 1)
            $opt    = Get-OptimalModel $vram $USE_ENG_MODE
            $gpuInfos += [PSCustomObject]@{ Index=$i; Name=$name; VramMB=[int]$vram; VramGB=$vramGB; Optimal=$opt }
            Write-Host "  GPU $i : $name  VRAM: ${vramGB} GB  optimal: $opt" -ForegroundColor Cyan
        }

        $selectedGpuIndex = 0
        if ($gpuCount -gt 1) {
            foreach ($g in $gpuInfos) {
                Write-Host "  [$($g.Index)]  GPU $($g.Index): $($g.Name) -- $($g.VramGB) GB -- optimal: $($g.Optimal)" -ForegroundColor Cyan
            }
            $gpuChoice = Read-Host "  Enter GPU index (0 to $($gpuCount-1))"
            if ($gpuChoice -match '^\d+$' -and [int]$gpuChoice -lt $gpuCount) {
                $selectedGpuIndex = [int]$gpuChoice
            }
        }

        $selectedGpu  = $gpuInfos[$selectedGpuIndex]
        $deviceString = if ($selectedGpuIndex -eq 0) { "cuda" } else { "cuda:$selectedGpuIndex" }
        $optModel     = Get-OptimalModel $selectedGpu.VramMB $USE_ENG_MODE

        # Model menu
        $models   = @("tiny","base","small","medium","large-v2")
        $idx = 1; $modelMenu = @{}
        foreach ($m in $models) {
            $fits = $selectedGpu.VramMB -ge (Get-VramReq $m)
            if ($fits) {
                $suffix = if ($m -eq $optModel) { " <- RECOMMENDED" } else { "" }
                Write-Host "  [$idx]  $m  -- $(Get-QualityLabel $m)$suffix" -ForegroundColor $(if ($m -eq $optModel) { "Green" } else { "Cyan" })
                $modelMenu[$idx.ToString()] = $m; $idx++
            }
        }
        Write-Host "  [$idx]  Keep current" -ForegroundColor Gray
        $currentModel = "medium"
        if (Test-Path $cfgPath) {
            $cc = Get-Content $cfgPath -Raw
            if ($cc -match 'model\s*=\s*"([^"]+)"') { $currentModel = $Matches[1] }
        }
        $modelMenu[$idx.ToString()] = $currentModel
        $modelChoice = (Read-Host "  Select model (1-$idx) [Enter = $optModel]").Trim()
        $chosenModel = if ($modelMenu.ContainsKey($modelChoice)) { $modelMenu[$modelChoice] } else { $optModel }

        $computeType = "float16"
        if ($chosenModel -eq "large-v2" -and $selectedGpu.VramMB -lt 8000) { $computeType = "int8" }

        # PTT uses medium as local fallback when server runs large model
        if ($chosenModel -in @("large-v2","large-v3","large-v1")) {
            Write-Host "  INFO: Server runs '$chosenModel'. PTT local fallback set to 'medium'." -ForegroundColor Cyan
            $chosenModel = "medium"; $computeType = "int8"
        }

        if (Test-Path $cfgPath) {
            $cfgContent = Get-Content $cfgPath -Raw
            $cfgContent = $cfgContent -replace 'model\s*=\s*"[^"]+"',        "model = `"$chosenModel`""
            $cfgContent = $cfgContent -replace 'device\s*=\s*"[^"]+"',       "device = `"$deviceString`""
            $cfgContent = $cfgContent -replace 'compute_type\s*=\s*"[^"]+"', "compute_type = `"$computeType`""
            $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
            [System.IO.File]::WriteAllText($cfgPath, $cfgContent, $utf8NoBom)
            Write-OK "config.toml updated: model=$chosenModel  device=$deviceString  compute_type=$computeType"
        }

    } else {
        Write-Host "  No CUDA GPU detected -- using CPU mode." -ForegroundColor Yellow
        if (Test-Path $cfgPath) {
            $cfgContent = Get-Content $cfgPath -Raw
            $cfgContent = $cfgContent -replace 'device\s*=\s*"[^"]+"',       'device = "cpu"'
            $cfgContent = $cfgContent -replace 'compute_type\s*=\s*"[^"]+"', 'compute_type = "int8"'
            $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
            [System.IO.File]::WriteAllText($cfgPath, $cfgContent, $utf8NoBom)
            Write-OK "config.toml set to CPU mode."
        }
    }
}



# =============================================================================
# =============================================================================
Write-Step 8 "Create launcher and desktop shortcut (Shag 8: Sozdat zapuskalnik i yarlik na rabochem stole)"
# =============================================================================

# Launcher bat -- Python path is quoted to handle spaces
$pyScript = if ($USE_ENG_MODE) { "whisper-ptt-eng.py" } else { "whisper-ptt.py" }
$launcherContent = "@echo off`r`nchcp 65001 >nul`r`nset PYTHONUTF8=1`r`ncd /d `"$INSTALL_DIR`"`r`n`"$PYTHON_EXE`" $pyScript`r`npause`r`n"
Set-Content -Path "$INSTALL_DIR\whisper-ptt-launcher.bat" -Value $launcherContent -Encoding ASCII
Write-OK "Created whisper-ptt-launcher.bat (Zapuskalnik whisper-ptt-launcher.bat sozdan)"

# Desktop shortcut
try {
    $desktop = [System.Environment]::GetFolderPath("Desktop")
    $shell   = New-Object -ComObject WScript.Shell
    $lnk     = $shell.CreateShortcut("$desktop\$SHORTCUT_NAME.lnk")
    $lnk.TargetPath      = "$INSTALL_DIR\whisper-ptt-launcher.bat"
    $lnk.WorkingDirectory = $INSTALL_DIR
    $lnk.IconLocation    = "$env:SystemRoot\System32\shell32.dll,14"
    $lnk.Description     = "Whisper Push-to-Talk ($VERSION_NAME)"
    $lnk.Save()
    Write-OK "Desktop shortcut created: $desktop\$SHORTCUT_NAME.lnk  (Yarlik na rabochem stole sozdan: $desktop\$SHORTCUT_NAME.lnk)"
} catch {
    Write-Warn "Could not create shortcut: $_ (Ne udalos sozdat yarlik: $_)"
    Write-Warn "Run manually: $INSTALL_DIR\whisper-ptt-launcher.bat  (Zapustite vruchnuyu: $INSTALL_DIR\whisper-ptt-launcher.bat)"
}

# =============================================================================
Write-Step 9 "Final verification (Shag 9: Itogovaya Proverka)"
# =============================================================================

$errCount = 0

# Python
if (Test-Path $PYTHON_EXE) {
    Write-OK "Python: $PYTHON_EXE  (Python: $PYTHON_EXE)"
} else {
    Write-Err "Python executable not found (Ispolniaemyy fayl Python ne nayden)"; $errCount++
}

# FFmpeg
if (Test-Ffmpeg) {
    Write-OK "FFmpeg: in PATH (FFmpeg: est v PATH)"
} else {
    $wgDir = Find-FfmpegInWinGet
    if ($wgDir) {
        Write-OK "FFmpeg: found at $wgDir (auto-loaded by whisper-ptt.py)  (FFmpeg: nayden v $wgDir, budet zagruzhen avtomaticheski)"
    } elseif (Test-Path "C:\ffmpeg\bin\ffmpeg.exe") {
        Write-OK "FFmpeg: found at C:\ffmpeg\bin (auto-loaded by whisper-ptt.py)  (FFmpeg: nayden v C:\ffmpeg\bin, zagruzitsya avtomaticheski)"
    } else {
        Write-Warn "FFmpeg: not found in PATH -- whisper-ptt.py will search at startup  (FFmpeg: ne v PATH -- whisper-ptt.py naydet pri zapuske)"
    }
}

# Python packages
foreach ($pkg in @("whisper", "torch", "sounddevice", "pynput", "pystray")) {
    & $PYTHON_EXE -c "import $pkg" 2>&1 | Out-Null
    if ($LASTEXITCODE -eq 0) { Write-OK "Package: $pkg  (Paket $pkg ustanovlen)" }
    else { Write-Err "Package missing: $pkg (Paket $pkg otsutstvuyet)"; $errCount++ }
}

# Project files
$mainScript = if ($USE_ENG_MODE) { "whisper-ptt-eng.py" } else { "whisper-ptt.py" }
if (Test-Path "$INSTALL_DIR\$mainScript") { Write-OK "File: $mainScript  (Fayl $mainScript naydyen)" } else { Write-Err "Missing: $mainScript  (Otsutstvuyet: $mainScript)"; $errCount++ }
if (Test-Path "$INSTALL_DIR\whisper_platform\__init__.py")      { Write-OK "Module: whisper_platform  (Modul whisper_platform nayden)" } else { Write-Err "Missing: whisper_platform  (Modul whisper_platform otsutstvuyet)"; $errCount++ }
if (Test-Path "$INSTALL_DIR\config.toml")     { Write-OK "File: config.toml  (Fayl config.toml nayden)"     } else { Write-Err "Missing: config.toml  (Fayl config.toml otsutstvuyet)";     $errCount++ }

# Confirm config language setting
try {
    $cfgContent = Get-Content "$INSTALL_DIR\config.toml" -Raw
    if ($USE_ENG_MODE) {
        if ($cfgContent -match 'language\s*=\s*"en"') { Write-OK "Config: language=en confirmed  (Nastroyka: yazyk=en podtverzhdyon)" }
        else { Write-Warn "Config: language is not en -- check config.toml  (Nastroyka: yazyk ne en -- proverte config.toml)" }
    } else {
        if ($cfgContent -match 'language\s*=\s*"ru"') { Write-OK "Config: language=ru confirmed  (Nastroyka: yazyk=ru podtverzhdyon)" }
        else { Write-Warn "Config: language is not ru -- check config.toml  (Nastroyka: yazyk ne ru -- proverte config.toml)" }
        if ($cfgContent -match 'model\s*=\s*"([^"]+)"') {
            Write-OK "Config: model=$($Matches[1]) confirmed  (Nastroyka: model=$($Matches[1]) podtverzhdena)"
        } else {
            Write-Warn "Config: model not found in config.toml  (Model ne naydena v config.toml)"
        }
    }
} catch {}

Write-Host ""
if ($errCount -eq 0) {
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host "  Installation complete! whisper_from_sssDeMoNsss ready  (Ustanovka zavershena! whisper_from_sssDeMoNsss gotov)"     -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "  Install dir : $INSTALL_DIR  (Papka ustanovki: $INSTALL_DIR)"                                        -ForegroundColor White
    Write-Host "  Hotkey      : Right Ctrl (change key in config.toml)  (Goryachaya klavisha: Praviy Ctrl, smenit v config.toml)"              -ForegroundColor White
    $langDisplay = if ($USE_ENG_MODE) { "English (en)" } else { "Russian (ru)" }
    # Read actual model from config.toml for display
    $cfgForDisplay = if (Test-Path "$INSTALL_DIR\config.toml") { Get-Content "$INSTALL_DIR\config.toml" -Raw } else { "" }
    $actualModel = "medium"
    if ($cfgForDisplay -match 'model\s*=\s*"([^"]+)"') { $actualModel = $Matches[1] }
    $modelDisplay = "$actualModel"
    Write-Host "  Version     : $VERSION_NAME  (Versiya: $VERSION_NAME)"                                           -ForegroundColor White
    Write-Host "  Language    : $langDisplay  (Yazyk: $langDisplay)"                                            -ForegroundColor White
    Write-Host "  Model       : $modelDisplay  (Model: $modelDisplay)"                                           -ForegroundColor White
    Write-Host "  Launch      : 'Whisper PTT' shortcut on Desktop  (Zapusk: yarlik 'Whisper PTT' na rabochem stole)"                  -ForegroundColor White
    Write-Host ""
    Write-Host "  NOTE: First launch will download Whisper model ~500 MB  (VNIMANIE: Pri pervom zapuske skachayetsya model Whisper ~500 MB)"           -ForegroundColor Yellow
    Write-Host ""
    Write-Host "  Optional -- disable Win+H voice input conflict:  (Optsionalno -- otklyuchit konflikt Win+H s golosovym vvodom Windows:)"                   -ForegroundColor Gray
    Write-Host "    powershell -ExecutionPolicy Bypass -File `"$INSTALL_DIR\disable-windows-voice.ps1`"" -ForegroundColor Gray
    $autostartScript    = if ($USE_ENG_MODE) { "setup-autostart-eng.ps1"       } else { "setup-autostart.ps1"    }
    $disableThisScript  = if ($USE_ENG_MODE) { "disable-setup-autostart-eng.ps1" } else { "disable-setup-autostart-ru.ps1" }
    $disableOtherScript = if ($USE_ENG_MODE) { "disable-setup-autostart-ru.ps1"  } else { "disable-setup-autostart-eng.ps1" }
    $otherInstallDir    = if ($USE_ENG_MODE) { "C:\whisper-ptt"                  } else { "C:\whisper-ptt-eng"              }

    # Check which autostart tasks currently exist
    $taskRU  = Get-ScheduledTask -TaskName "Whisper PTT Autostart"        -ErrorAction SilentlyContinue
    $taskENG = Get-ScheduledTask -TaskName "Whisper PTT ENG-RU Autostart" -ErrorAction SilentlyContinue

    Write-Host ""
    Write-Host "------------------------------------------------------------" -ForegroundColor Yellow
    Write-Host "  Autostart management: (Upravleniye avtozagruzkoyi:)" -ForegroundColor White
    Write-Host ""
    Write-Host "  Current status: (Tekushchiy status:)" -ForegroundColor Gray
    if ($taskRU)  { Write-Host "    RU-ENG  (C:\whisper-ptt)     : [ENABLED]  (VKLYUCHENA)"  -ForegroundColor Green  }
    else          { Write-Host "    RU-ENG  (C:\whisper-ptt)     : [disabled]  (vyklyuchena)" -ForegroundColor Gray   }
    if ($taskENG) { Write-Host "    ENG-RU  (C:\whisper-ptt-eng) : [ENABLED]  (VKLYUCHENA)"  -ForegroundColor Cyan   }
    else          { Write-Host "    ENG-RU  (C:\whisper-ptt-eng) : [disabled]  (vyklyuchena)" -ForegroundColor Gray   }
    Write-Host ""
    Write-Host "  What do you want to do? (Chto vy khotite sdelat?)" -ForegroundColor White
    Write-Host ""
    Write-Host "  [1]  Enable autostart for THIS version ($VERSION_NAME)  (Vklyuchit avtozagruzku ETOY versii)" -ForegroundColor Green
    Write-Host "  [2]  Disable autostart for THIS version ($VERSION_NAME)  (Vyklyuchit avtozagruzku ETOY versii)" -ForegroundColor Yellow
    Write-Host "  [3]  Disable autostart for THE OTHER version  (Vyklyuchit avtozagruzku DRUGOY versii)" -ForegroundColor Yellow
    Write-Host "  [4]  Disable autostart for BOTH versions  (Vyklyuchit avtozagruzku OBEIKH versiy)" -ForegroundColor Red
    Write-Host "  [5]  Skip -- do nothing  (Propustit -- nichego ne delat)" -ForegroundColor Gray
    Write-Host ""
    $autoChoice = Read-Host "  Enter 1-5 (Vvedite 1-5)"
    $autoChoice = $autoChoice.Trim()

    switch ($autoChoice) {
        "1" {
            Write-Host ""
            Write-Host "  Enabling autostart for $VERSION_NAME... (Vklyuchayem avtozagruzku dlya $VERSION_NAME...)" -ForegroundColor Cyan
            & powershell -ExecutionPolicy Bypass -File "$INSTALL_DIR\$autostartScript"
            exit 0
        }
        "2" {
            Write-Host ""
            Write-Host "  Disabling autostart for $VERSION_NAME... (Vyklyuchayem avtozagruzku dlya $VERSION_NAME...)" -ForegroundColor Yellow
            & powershell -ExecutionPolicy Bypass -File "$INSTALL_DIR\$disableThisScript"
        }
        "3" {
            Write-Host ""
            Write-Host "  Disabling autostart for the other version... (Vyklyuchayem avtozagruzku dlya drugoy versii...)" -ForegroundColor Yellow
            $otherDisable = "$otherInstallDir\$disableOtherScript"
            if (Test-Path $otherDisable) {
                & powershell -ExecutionPolicy Bypass -File $otherDisable
            } else {
                # Run inline if file not present in other dir
                & powershell -ExecutionPolicy Bypass -File "$INSTALL_DIR\$disableOtherScript"
            }
        }
        "4" {
            Write-Host ""
            Write-Host "  Disabling autostart for BOTH versions... (Vyklyuchayem avtozagruzku OBEIKH versiy...)" -ForegroundColor Red
            & powershell -ExecutionPolicy Bypass -File "$INSTALL_DIR\disable-setup-autostart-ru.ps1"
            & powershell -ExecutionPolicy Bypass -File "$INSTALL_DIR\disable-setup-autostart-eng.ps1"
        }
        default {
            Write-Host "  Skipping autostart setup. (Propusk nastroyki avtozagruzki.)" -ForegroundColor Gray
        }
    }
} else {
    Write-Host "============================================================" -ForegroundColor Red
    Write-Host "  Installation finished with $errCount error(s)  (Ustanovka zavershena s $errCount oshibkoy(-ami))"                    -ForegroundColor Red
    Write-Host "============================================================" -ForegroundColor Red
    Write-Host "  See README_FINAL.md for troubleshooting.  (Smotrite README_FINAL.md dlya ustraneniya nepoladok.)"                         -ForegroundColor Yellow
}

Write-Host ""
Read-Host "Press Enter to exit (Nazhmite Enter dlya vyhoda)"
